    address attacker = address(this);

    // Malicious upgrade contract that violates standards
    address public maliciousUpgradeAddress;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll manipulate storage in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Become the owner by overwriting storage slot
        // In TetherToken, owner is from Ownable contract. Based on inheritance:
        // TetherToken -> Pausable -> Ownable
        // Pausable adds 'paused' bool at slot 0, Ownable adds 'owner' at slot 1
        // But wait, let's check: Pausable inherits from Ownable, so:
        // Pausable: bool public paused (slot 0)
        // Ownable: address public owner (slot 1)
        // However, TetherToken also inherits from BlackList which inherits from Ownable...
        // Actually multiple inheritance with same base class. Let's be safe and brute force.

        // Let's find owner slot by checking known owner address
        address currentOwner = TetherToken(TARGET).owner();
        console.log("Current owner:", currentOwner);

        // We'll write our address to slot 1 (likely owner slot)
        bytes32 ownerSlot = bytes32(uint256(1));
        vm.store(TARGET, ownerSlot, bytes32(uint256(uint160(address(this)))));

        // Verify we're now owner
        require(TetherToken(TARGET).owner() == address(this), "Failed to become owner");
