        require(deprecated == true, "deprecated should be true");
        console.log("Successfully deprecated contract");
        assertEq(TetherToken(TARGET).deprecated(), true, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

